/* Account screens use the real Supabase-backed StudyCloud client. */
(()=>{
  'use strict';
  const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let mode='signin',lastStatus={configured:false,user:null,status:'initializing'},context=null,notice=null,busy=false,renderQueued=false;
  function message(text,error=false){notice={text,error};const box=document.querySelector('#auth-message');if(box){box.textContent=text;box.className='auth-message'+(error?' error':'');box.hidden=false}}
  function setBusy(){context?.host.querySelectorAll('[data-auth-mode],#auth-submit,#sync-now,#sign-out,#import-guest,[data-conflict-path]').forEach(b=>{b.disabled=busy||(b.id==='auth-submit'&&!lastStatus.configured)})}
  function readableError(error){const t=String(error?.message||error||'操作未能完成，请重试。');if(/Invalid login credentials/i.test(t))return'邮箱或密码不正确，请检查后再试。';if(/Email not confirmed/i.test(t))return'请先打开邮箱中的验证链接，再回来登录。';if(/rate limit|too many requests/i.test(t))return'请求较频繁，请稍后再试。';if(/Failed to fetch|NetworkError/i.test(t))return'网络暂时无法连接，请检查网络后重试。';return t}
  const showValue=cell=>{const value=cell&&typeof cell==='object'&&'deleted'in cell?(cell.deleted?undefined:cell.value):cell;return value===undefined?'（已删除）':typeof value==='string'?value:JSON.stringify(value,null,2)};
  function fieldLabel(x){let p;try{p=JSON.parse(x.path)}catch{return '学习记录'}const names={drafts:'作答草稿',essays:'作文',tasks:'学习任务',words:'词汇状态',results:'听力成绩',mistakes:'错题',read:'专题阅读',settings:'个人设置',mock:'模拟卷',prompt:'题目',draft:'草稿',answers:'作答',plan:'学习计划',day:'学习日'};return p.map(k=>names[k]||k).join(' · ')}
  async function run(button,action,done){if(button.disabled||busy)return;busy=true;setBusy();const before=button.textContent;button.textContent='处理中…';try{const result=await action();if(done)done(result)}catch(error){message(readableError(error),true)}finally{busy=false;if(renderQueued&&context&&location.hash==='#account'){renderQueued=false;render(context.host,context.ctx)}else{setBusy();if(button.isConnected)button.textContent=before}}}
  function render(host,ctx){context={host,ctx,configured:lastStatus.configured};const status=lastStatus,c=window.StudyCloud;
    host.innerHTML=ctx.heading('YOUR PERSONAL ORBIT',status.user?'你的进度，随你同行。':'登录，接续每一次进步。',status.user?'电脑练习，手机复习。同一账号，接续你的任务、错题和草稿。':'邮箱注册个人账号，学习记录属于你。也可以先以游客身份体验。')+
      `<div class="settings-grid"><section class="panel account-panel">${status.user&&!status.recovery?profile(status):form(status)}<div id="auth-message" class="auth-message" role="status" aria-live="polite" hidden></div></section><section class="panel profile-card"><div class="card-kicker">ONE ACCOUNT · EVERY DEVICE</div><h2>把努力，留在你的轨道里。</h2><div class="account-benefits"><p><span>01</span><strong>自动接续进度</strong><small>任务、词汇、听力答案与写作草稿随账号保存。</small></p><p><span>02</span><strong>每个人的独立空间</strong><small>公开课程，个人进度。其他账号不能读取你的学习记录。</small></p><p><span>03</span><strong>离线也能继续</strong><small>断网时先保存在当前设备，重新联网后尝试同步。</small></p></div><p class="hint">在公共电脑上学习后，请退出账号。访客进度不会自动导入登录账号，你可以登录后自行选择导入。</p><button class="secondary" data-go="home">${status.user?'返回学习空间':'先体验课程'} →</button></section></div>${status.user?conflicts(c?.getConflicts?.()||[]):''}`;
    host.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>{if(busy)return;notice=null;mode=b.dataset.authMode;render(host,ctx)});
    const f=host.querySelector('#auth-form');if(f)f.onsubmit=async event=>{event.preventDefault();if(busy)return;const intent=status.recovery?'recovery':mode,b=host.querySelector('#auth-submit'),email=f.elements.email?.value.trim(),password=f.elements.password?.value;if(['signup','recovery'].includes(intent)&&password!==f.elements.confirmPassword.value){message('两次输入的密码不一致。',true);return}await run(b,()=>intent==='recovery'?c.updatePassword(password):intent==='reset'?c.resetPassword(email):intent==='signup'?c.signUp(email,password):c.signIn(email,password),result=>{if(intent==='recovery'){mode='signin';render(host,ctx);message('密码已更新，你可以继续使用当前账号。')}else if(intent==='reset')message('如果这个邮箱已经注册，我们会向它发送重置邮件，请检查收件箱及垃圾邮件。');else if(intent==='signup'){if(lastStatus.user||result?.user){ctx.toast('账号已创建并登录，欢迎进入个人学习空间');location.hash='home'}else{message('注册请求已提交。请打开邮箱中的确认链接后登录，并检查垃圾邮件。');if(f.isConnected)f.reset()}}else if(lastStatus.user){ctx.toast('登录成功，已进入你的个人学习空间');location.hash='home'}})};
    const sync=host.querySelector('#sync-now');if(sync)sync.onclick=()=>run(sync,()=>c.syncNow(),()=>message('已完成同步检查。'));
    const logout=host.querySelector('#sign-out');if(logout)logout.onclick=()=>run(logout,()=>c.signOut(),()=>{ctx.toast('已退出账号');mode='signin';render(host,ctx)});
    const guest=host.querySelector('#import-guest');if(guest)guest.onclick=()=>{if(confirm('把此设备的游客练习导入当前账号？已有不同内容会提示你选择，建议先导出备份。'))run(guest,()=>c.importGuest(),()=>{message('已处理游客进度，请检查同步状态及冲突提示。');render(host,ctx)})};
    host.querySelectorAll('[data-conflict-path]').forEach(b=>b.onclick=()=>run(b,()=>c.resolveConflict(b.dataset.conflictPath,b.dataset.choice),()=>render(host,ctx)));
    if(notice)message(notice.text,notice.error);setBusy();
  }
  function form(s){const recovery=!!s.recovery;return `<div class="auth-tabs">${!recovery?[['signin','登录'],['signup','创建账号']].map(([k,t])=>`<button type="button" data-auth-mode="${k}" class="${mode===k?'active':''}">${t}</button>`).join(''):'<strong>设置新密码</strong>'}</div>${!s.configured?'<div class="notice">账号服务尚未启用。管理员完成云服务配置后即可注册与同步；现在可以先以游客身份体验。</div>':''}<form id="auth-form" class="auth-form">${!recovery?'<label for="auth-email">邮箱地址</label><input id="auth-email" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="you@example.com">':''}${mode!=='reset'||recovery?`<label for="auth-password">${recovery?'新密码':'密码'}</label><input id="auth-password" name="password" type="password" autocomplete="${mode==='signup'||recovery?'new-password':'current-password'}" required minlength="${mode==='signup'||recovery?8:1}" maxlength="128" placeholder="${mode==='signup'||recovery?'至少 8 个字符':'输入你的密码'}">`:''}${mode==='signup'||recovery?'<label for="auth-confirm">确认密码</label><input id="auth-confirm" name="confirmPassword" type="password" autocomplete="new-password" required minlength="8" maxlength="128" placeholder="再次输入密码">':''}<button id="auth-submit" class="primary auth-submit" type="submit" ${!s.configured?'disabled':''}>${recovery?'更新密码':mode==='signup'?'创建我的账号':mode==='reset'?'发送重置邮件':'登录我的空间'} →</button></form><div class="account-actions">${!recovery?`<button type="button" class="quiet" data-auth-mode="${mode==='reset'?'signin':'reset'}">${mode==='reset'?'返回登录':'忘记密码？'}</button>`:''}<button class="quiet" data-go="home">以游客身份浏览</button></div><p class="password-note">密码由身份服务安全处理，不会写入课程仓库或学习进度文件。</p>`}
  function profile(s){return `<div class="row-between"><span class="status-chip">PERSONAL ACCOUNT</span><span class="sync-state" data-state="${safe(s.status)}">${safe(s.message||'同步准备中')}</span></div><div class="account-avatar">${safe((s.user.email||'U')[0].toUpperCase())}</div><h2 class="break-word">${safe(s.user.email||'已登录')}</h2><p class="hint">${s.lastSyncAt?'最近同步：'+new Date(s.lastSyncAt).toLocaleString('zh-CN'):'进度会在练习后自动保存。'}</p>${s.pending?'<div class="notice">还有本地变更等待上传，请保持页面打开并检查网络。</div>':''}<div class="button-row"><button id="sync-now" class="primary">立即同步</button><button class="secondary" data-go="settings">备份与偏好</button></div>${s.guestAvailable?'<button class="quiet" id="import-guest">将此设备游客进度导入当前账号 →</button>':''}<div class="button-row"><button id="sign-out" class="quiet">退出登录</button></div>${s.recovery?'<button class="secondary" data-auth-mode="recover">设置新密码</button>':''}`}
  function conflicts(items){if(!items.length)return'';return `<section class="panel space-top"><h2>选择要保留的内容</h2><p class="hint">两台设备修改了同一项。两份内容都已保留，请比较后选择。</p>${items.map(x=>`<div class="conflict-card"><h3>${safe(fieldLabel(x))}</h3><div class="two-grid"><div><span class="tag">这台设备</span><pre>${safe(showValue(x.local).slice(0,1200))}</pre><button class="secondary small" data-conflict-path="${safe(x.path)}" data-choice="local">保留本机内容</button></div><div><span class="tag">云端</span><pre>${safe(showValue(x.remote).slice(0,1200))}</pre><button class="primary small" data-conflict-path="${safe(x.path)}" data-choice="remote">使用云端内容</button></div></div></div>`).join('')}</section>`}
  window.AccountUI={render,onStatus(s){const identityChanged=(s.user?.id||null)!==(lastStatus.user?.id||null)||!!s.recovery!==!!lastStatus.recovery;lastStatus=s;if(identityChanged)notice=null;if(location.hash==='#account'&&context){if(identityChanged||s.configured!==context.configured){render(context.host,context.ctx);return}const active=document.activeElement;if(s.user&&!s.recovery&&(!active||!context.host.contains(active)||!['INPUT','TEXTAREA'].includes(active.tagName))){if(busy)renderQueued=true;else render(context.host,context.ctx)}}},getStatus:()=>lastStatus};
})();
